def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "grab_napkin": And([
            self.item_at(self.iron, self.breakfast_table),
            self.iron_hot,
            Not(self.iron_detected),
            self.obstacle_awareness
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
